import {SDK_COMMIT} from './sdk.js';
export const AGENTS=[['Research Agent','Research & analysis'],['Development Agent','Software development'],['Data Agent','Processing & enrichment'],['Verification Agent','Checking information'],['Reporting Agent','Business reports']];
export const SERVICES=[['Research Dataset','Premium dataset access','Dataset preview generated'],['Cloud Compute','An isolated compute job','Compute result generated'],['Search API','A paid search request','Search result generated'],['Data Verification','A verification operation','Verification report generated'],['Advanced Analysis','Specialized analysis','Analysis summary generated']];
export const STAGES=[['requested','Request','application'],['quoted','Quote','application'],['approved','Authorize','application'],['signed','Sign','SDK'],['submitted','Submit','application'],['applied','Execute & read','SDK'],['fulfilled','Service receipt','application + SDK']];
export function minor(value){const s=String(value).trim();if(!/^\d+(\.\d{1,2})?$/.test(s))throw Error('Use a nonnegative amount with at most two decimals.');const [a,b='']=s.split('.'),n=Number(a)*100+Number(b.padEnd(2,'0'));if(!Number.isSafeInteger(n)||n>10000000)throw Error('Amount exceeds the demo limit.');return n;}
export const credits=n=>(Number(n)/100).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
export function reconciliation(state){const balances=state.balances.map(b=>Number(b.balance_minor)),agents=balances.slice(0,5).reduce((a,b)=>a+b,0),providers=balances.slice(5,10).reduce((a,b)=>a+b,0),issuer=balances[10],volume=state.requests.filter(r=>r.payment).reduce((n,r)=>n+r.amount_minor,0);return {opening_minor:state.opening_supply_minor,agent_minor:agents,provider_minor:providers,issuer_minor:issuer,volume_minor:volume,total_minor:agents+providers+issuer,balanced:agents+providers+issuer===state.opening_supply_minor&&providers===volume&&agents===state.opening_supply_minor-volume};}
export class PaymentNetwork{
 constructor(sdk,{session=()=>globalThis.crypto.randomUUID()}={}){this.sdk=sdk;this.newSession=session;this.reset();}
 reset(scenario='purchase',guided=true){this.scenario=scenario;this.guided=guided;this.elapsed=0;this.age=0;this.running=false;this.speed=1;this.selectedAgent=0;this.selectedProvider=0;this.currentId=null;this.journal=[];this.error=null;this.state=this.sdk.reset(this.newSession());if(scenario==='policy'){const p={...this.state.policies[0],maximum_minor:1000};this.perform('policy',{agent_index:0,policy:p});}this.begin(0,0,guided);return this;}
 perform(command,args={}){const input={command,...args},result=this.sdk.call(input);this.journal.push(input);this.state=result.snapshot||result;return result;}
 get current(){return this.state.requests.find(r=>r.request_id===this.currentId)||null;}
 begin(agent=this.selectedAgent,provider=this.selectedProvider,guided=false){const r=this.perform('request',{agent_index:agent,provider_index:provider});this.currentId=r.request_id;this.selectedAgent=agent;this.selectedProvider=provider;this.guided=guided;this.running=true;this.age=0;return this.current;}
 selectAgent(index){this.selectedAgent=index;this.currentId=this.state.requests.filter(r=>r.agent_index===index).at(-1)?.request_id||null;this.running=false;this.guided=false;}
 selectRequest(id){const r=this.state.requests.find(r=>r.request_id===id);if(!r)return;this.currentId=id;this.selectedAgent=r.agent_index;this.selectedProvider=r.provider_index;this.running=false;this.guided=false;}
 step(){const r=this.current;if(!r){this.running=false;return;}const command={requested:'quote',quoted:'authorize',approved:'sign',signed:'submit',submitted:'apply',applied:'fulfill'}[r.status];if(!command){this.running=false;return;}this.perform(command,{request_id:r.request_id});if(['awaiting_approval','rejected','failed','fulfilled'].includes(this.current.status))this.running=false;if(this.current.status==='fulfilled'&&this.scenario==='duplicate')this.perform('duplicate',{request_id:r.request_id});}
 tick(dt){if(!this.running)return;this.elapsed+=dt*this.speed;this.age+=dt*this.speed;const interval=this.guided?4.5:1.1;while(this.age>=interval&&this.running){this.age-=interval;try{this.step();}catch(e){this.running=false;this.error=e.message;throw e;}}}
 approve(){this.perform('approve',{request_id:this.currentId});this.running=true;this.age=0;}
 reject(){this.perform('reject',{request_id:this.currentId});this.running=false;}
 retry(){const r=this.perform('retry',{request_id:this.currentId});this.currentId=r.request_id;this.running=this.current.status==='requested';this.guided=false;this.age=0;}
 duplicate(){this.perform('duplicate',{request_id:this.currentId});}
 policy(index,p){this.perform('policy',{agent_index:index,policy:p});}
 price(index,n){this.perform('price',{provider_index:index,amount_minor:n});}
 verify(request=this.current,edited){if(!request?.transaction)throw Error('This request has no signed Coins transaction.');return this.sdk.call({command:'verify',signed_transaction:request.transaction.signed_transaction,...(edited===undefined?{}:{edited_amount_minor:edited})});}
 probe(request=this.current){if(!request?.transaction)throw Error('No signed transaction.');return this.sdk.call({command:'probe',signed_transaction:request.transaction.signed_transaction});}
 get accounting(){return reconciliation(this.state);}
 export(){return {format:'nunchi-agent-payments/1',sdk_commit:SDK_COMMIT,session_id:this.state.session_id,scope:'Local SDK Coins ledger and Oracle execution. Public test identities, isolated demo asset, fictional services. No real money, network finality, state-root proof or production payment security.',journal:structuredClone(this.journal),state:structuredClone(this.sdk.snapshot()),reconciliation:this.accounting};}
}

